    save: function save(val) {
      var _this = this;
      var submitForm = {
        ciId: this.devHideDetail.ciId,
        ciIcon: this.devHideDetail.icon,
        authData: this.devHideDetail.authData,
        ciLabel: this.devHideDetail.label,
        ciName: this.devHideDetail.name,
        maxAttrEntityCount: 999999999,
        maxRelEntityCount: 999999999,
        uuid: this.devHideDetail.uuid,
        id: this.devHideDetail.id,
        attrEntityData: {}
      };
      var toParams = JSON.parse(JSON.stringify(this.formData[val.formName].hideField.fieldData));
      toParams = [].concat(_toConsumableArray(toParams), _toConsumableArray(this.xinArr));
      toParams.forEach(function (item) {
        var attrValue = [];
        if (_this.devHideDetail[item.name]) {
          if (_this.devHideDetail[item.name] instanceof Array) {
            // attrValue = this.submitForm[item.name]
            if (item.type === 'datetimerange') attrValue = [_this.devHideDetail[item.name][0] + ',' + _this.devHideDetail[item.name][1]];else attrValue = _this.devHideDetail[item.name];
          } else attrValue = [_this.devHideDetail[item.name]];
        } else {
          attrValue = [];
        }
        submitForm.attrEntityData['attr_' + item.id] = {
          type: item.type,
          valueList: attrValue,
          actualValueList: attrValue
        };
      });
      this.$refs['submitForm' + val.formName][0].validate(function (valid) {
        if (valid) {
          _this.saveLoading = true;
          cientityValidate(submitForm).then(function (res) {
            if (res.Return.hasChange) {
              cientityBatchsave({
                needCommit: true,
                ciEntityList: [submitForm]
              }).then(function (res) {
                _this.$message({
                  type: 'success',
                  message: '保存成功！'
                });
                _this.bookHideDetailForm = JSON.parse(JSON.stringify(_this.devHideDetail));
              });
            } else {
              _this.$message({
                type: 'warning',
                message: '未校验到数据修改！'
              });
            }
          }).finally(function () {
            _this.formDisabled = true;
            _this.saveLoading = false;
            _this.showHide = false;
          });
        }
      });
      // cientityValidate
    },
    mcancel: function mcancel() {
